#include <vector>
#include <array>
#include <cstddef>
#include <omp.h>

struct Point {
   double x, y;
};

void countQuadrants(std::vector<Point> const& points, std::array<size_t, 4> &bins) {
    bins = {0u, 0u, 0u, 0u};

    #pragma omp parallel
    {
        std::array<size_t, 4> local = {0u, 0u, 0u, 0u};

        #pragma omp for nowait
        for (std::size_t i = 0; i < points.size(); ++i) {
            const double x = points[i].x;
            const double y = points[i].y;

            // Treat points on axes as quadrant I by using >= comparisons,
            // matching the provided example where (0.1, 2) counts in bin 0.
            if (x >= 0.0) {
                if (y >= 0.0) {
                    ++local[0]; // quadrant I
                } else {
                    ++local[3]; // quadrant IV
                }
            } else {
                if (y >= 0.0) {
                    ++local[1]; // quadrant II
                } else {
                    ++local[2]; // quadrant III
                }
            }
        }

        #pragma omp critical
        {
            bins[0] += local[0];
            bins[1] += local[1];
            bins[2] += local[2];
            bins[3] += local[3];
        }
    }
}
